import{_ as n,o as a,c as p,ai as e}from"./chunks/framework.Ba-VnP44.js";const u=JSON.parse('{"title":"02 任务执行","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/coding-sop/02-task-execution.md","filePath":"ai/productivity/coding-sop/02-task-execution.md"}'),l={name:"ai/productivity/coding-sop/02-task-execution.md"};function i(r,s,t,c,b,d){return a(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="_02-任务执行" tabindex="-1">02 任务执行 <a class="header-anchor" href="#_02-任务执行" aria-label="Permalink to “02 任务执行”">​</a></h1><blockquote><p>把需求交代清楚，让 AI 分析方案、拆解任务、连续编码，而不是每做一步都回来问一次「要不要继续」。人只在关键决策点拍板。</p></blockquote><h2 id="一、什么时候用" tabindex="-1">一、什么时候用 <a class="header-anchor" href="#一、什么时候用" aria-label="Permalink to “一、什么时候用”">​</a></h2><table tabindex="0"><thead><tr><th>任务类型</th><th>执行方式</th></tr></thead><tbody><tr><td>单文件小修改、文案、明确的小 Bug</td><td>说清目标与边界 → 直接做 → 验证</td></tr><tr><td>新增接口、业务功能、跨文件修改</td><td>分析影响 → 简要方案 → 实施 → 测试</td></tr><tr><td>多模块改造、数据库变更、系统集成、核心业务重构</td><td>完整分析 → 方案拆解 → 风险检查 → 分阶段执行</td></tr><tr><td>已有一份冻结计划，要连续做完</td><td>按本页的连续执行机制推进</td></tr></tbody></table><p><strong>判断标准：如果改错了需要回滚多个文件，就先做方案。</strong> 修改一行代码，只要涉及订单状态、库存扣减或资金计算，也可能是高等级任务。</p><p><strong>不是输入越详细越好，而是影响 AI 正确完成任务的信息不能缺失。</strong> 能从项目里查到的，不让用户重复写。</p><h3 id="人什么时候必须参与" tabindex="-1">人什么时候必须参与 <a class="header-anchor" href="#人什么时候必须参与" aria-label="Permalink to “人什么时候必须参与”">​</a></h3><ul><li>业务规则有两种以上合理解释。</li><li>涉及权限、支付、资金、库存等关键业务。</li><li>需要删除数据、改生产配置、执行不可逆操作。</li><li>要改已有接口签名或返回结构。</li><li>要新增核心依赖、升级框架版本。</li><li>要动禁改区或没有测试覆盖的老代码。</li></ul><p>确认时人只需回答三件事：<strong>选哪个方案、哪些边界要加、哪些风险不接受</strong>。不替 AI 写代码。</p><h2 id="二、操作步骤" tabindex="-1">二、操作步骤 <a class="header-anchor" href="#二、操作步骤" aria-label="Permalink to “二、操作步骤”">​</a></h2><h3 id="_2-1-任务输入结构" tabindex="-1">2.1 任务输入结构 <a class="header-anchor" href="#_2-1-任务输入结构" aria-label="Permalink to “2.1 任务输入结构”">​</a></h3><p>沿用四段式，再补两个真正影响效率的部分：</p><table tabindex="0"><thead><tr><th>部分</th><th>需要回答的问题</th><th>是否必填</th></tr></thead><tbody><tr><td>背景</td><td>当前情况是什么？</td><td>视任务而定</td></tr><tr><td>目标</td><td>具体要实现什么？</td><td>必填</td></tr><tr><td>约束</td><td>哪些能改、哪些不能改？</td><td>必填，至少说明关键边界</td></tr><tr><td>输出格式</td><td>最终交付什么？</td><td>必填，默认输出执行结果</td></tr><tr><td>任务分级</td><td>需要多大程度的分析和验证？</td><td>由 AI 初步判断</td></tr><tr><td>验收标准</td><td>怎样才算完成？</td><td>必填，简单任务可简写</td></tr></tbody></table><p>简单任务一句话加必要限制就够；复杂任务才补业务背景、流程和验收条件。</p><h3 id="_2-2-不同任务怎么交代" tabindex="-1">2.2 不同任务怎么交代 <a class="header-anchor" href="#_2-2-不同任务怎么交代" aria-label="Permalink to “2.2 不同任务怎么交代”">​</a></h3><table tabindex="0"><thead><tr><th>任务</th><th>重点</th><th>一句话要求</th></tr></thead><tbody><tr><td>新功能</td><td>明确功能行为、业务规则、与现有系统关系</td><td>优先沿用现有逻辑；规则冲突先集中提问，不自行编造</td></tr><tr><td>Bug 修复</td><td>先找根因，不处理表面现象</td><td>给完整报错 + 复现步骤 + 已排查项，先定位再修</td></tr><tr><td>功能调整</td><td>明确变的部分和必须不变的部分</td><td>保持原有字段、排序、接口与流程</td></tr><tr><td>代码重构</td><td>重构内部实现，不改变业务行为</td><td>保持接口签名与数据结构兼容，先补行为测试</td></tr><tr><td>系统对接</td><td>数据结构、通信规则、失败与重复执行</td><td>接口调用成功 ≠ 业务数据同步成功；考虑幂等与超时</td></tr></tbody></table><h3 id="_2-3-让-ai-主动发现缺失信息" tabindex="-1">2.3 让 AI 主动发现缺失信息 <a class="header-anchor" href="#_2-3-让-ai-主动发现缺失信息" aria-label="Permalink to “2.3 让 AI 主动发现缺失信息”">​</a></h3><p>把信息分三类，不要让用户事先想全：</p><table tabindex="0"><thead><tr><th>类型</th><th>含义</th><th>处理方式</th></tr></thead><tbody><tr><td>已确认</td><td>用户明确说明，或代码和项目资料能验证</td><td>直接采用</td></tr><tr><td>可推断</td><td>能从现有代码、配置、历史实现合理确认</td><td>查证据后采用</td></tr><tr><td>待确认</td><td>现有资料无法确定，且不同选择会影响结果</td><td>集中提问</td></tr></tbody></table><p><strong>不能把自己的猜测当成已确认的业务规则。</strong></p><ul><li>能从项目里确认的，不问用户。</li><li>不影响业务正确性的细节，按项目现有规范处理。</li><li>涉及业务规则、数据一致性、权限、安全、不可逆操作的，不能猜。</li><li>所有阻塞问题一次性提出；没有阻塞就直接执行，不逐步问「要不要继续」。</li></ul><h3 id="_2-4-方案与拆解" tabindex="-1">2.4 方案与拆解 <a class="header-anchor" href="#_2-4-方案与拆解" aria-label="Permalink to “2.4 方案与拆解”">​</a></h3><p>方案要回答五个维度：<strong>数据</strong>（表、索引、约束、迁移、事务）、<strong>接口</strong>（路径、入出参、错误码、兼容性）、<strong>模块与分层</strong>（落在哪个包、依赖方向）、<strong>兼容与影响</strong>（老数据、调用方、开关、定时任务）、<strong>验证方式</strong>（哪些测试、哪些命令、哪些人工核对）。</p><p>凡有多种做法，给出 2–3 个方案并比较：改动范围、数据影响、兼容性、回滚成本、验证难度。取舍顺序是<strong>业务正确性 → 兼容性 → 改动范围 → 复用 → 可验证性 → 代码美观</strong>。</p><p>方案里必须有「本次不做项」和「修改范围三栏」：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>允许修改：</span></span>
<span class="line"><span>- backend/.../service/WorkOrderService.java</span></span>
<span class="line"><span>- web/src/api/mes.ts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止修改：</span></span>
<span class="line"><span>- 任何已有接口路径与方法签名</span></span>
<span class="line"><span>- legacy/ 目录下的历史逻辑</span></span>
<span class="line"><span>- pom.xml、package.json（本次不新增依赖）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>必须保持兼容：</span></span>
<span class="line"><span>- GET /api/mes/work-orders 的返回结构</span></span>
<span class="line"><span>- 现有状态机的流转规则</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>拆解到什么粒度才合格：<strong>能独立完成、能独立验收、一次提交能覆盖</strong>。按依赖顺序排：<code>数据层 → 后端服务 → 接口层 → 前端 → 测试 → 文档</code>。前后端并行有前提——接口契约先冻结。</p><p>子任务表：</p><table tabindex="0"><thead><tr><th>编号</th><th>子任务</th><th>涉及文件</th><th>依赖</th><th>完成标准</th><th>验收方式</th></tr></thead><tbody><tr><td>T1</td><td>数据库字段与索引</td><td>sql/x.sql</td><td>无</td><td>脚本可重复执行</td><td>本地执行 + 查 information_schema</td></tr><tr><td>T2</td><td>后端领域规则</td><td>Service.java</td><td>T1</td><td>规则实现且有单测</td><td>单测通过</td></tr><tr><td>T3</td><td>接口与 DTO</td><td>Controller.java、DTO</td><td>T2</td><td>返回结构符合契约</td><td>接口冒烟</td></tr><tr><td>T4</td><td>前端列表与表单</td><td>Vue 文件、api.ts</td><td>T3</td><td>取数正常</td><td>浏览器操作 + 编译</td></tr></tbody></table><p><strong>完成标准不能写「完成开发」</strong>，要写成具体命令、diff 特征或页面行为。</p><h3 id="_2-5-连续执行机制" tabindex="-1">2.5 连续执行机制 <a class="header-anchor" href="#_2-5-连续执行机制" aria-label="Permalink to “2.5 连续执行机制”">​</a></h3><p>连续执行不是发一段「你自己写完吧」，而是三样东西：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th><th>什么时候读</th></tr></thead><tbody><tr><td><code>TASK-PLAN.md</code></td><td>子任务、依赖、完成标准、不做项、停止条件</td><td>每轮开始</td></tr><tr><td><code>PROGRESS.md</code></td><td>每轮做了什么、命令输出、失败记录、下一步</td><td>每轮开始、恢复会话时</td></tr><tr><td><code>DECISIONS.md</code>（可选）</td><td>执行中的小决定及依据</td><td>争议时回查</td></tr></tbody></table><p>状态只有五种：<code>pending → in_progress → done / blocked / skipped</code>。<code>done</code> 必须有证据和一个提交 hash；<code>blocked</code> 必须写明原因和需要谁提供什么。</p><p>每轮六步，不能跳：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 读状态    TASK-PLAN.md + PROGRESS.md 末尾</span></span>
<span class="line"><span>2. 选任务    按依赖顺序选下一个 pending，标 in_progress</span></span>
<span class="line"><span>3. 执行      只做这一个子任务，遵守范围与不做项</span></span>
<span class="line"><span>4. 验证      跑该任务的完成标准对应的命令</span></span>
<span class="line"><span>5. 记录      写 PROGRESS.md，更新状态快照</span></span>
<span class="line"><span>6. 提交      验证通过则提交，进入下一轮</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>失败分类，不要一律重试</strong>：代码错误可重试最多三轮；环境问题（缺服务、缺权限、缺数据）标 blocked；认知问题（反复改不对、改 A 坏 B）停手回项目分析；需求冲突交人确认。</p><p>每轮结束检查实际改动文件是否在允许范围内。出现这些立即停：AI 说「顺手把……也改了」、开始改依赖文件或公共模块、同一问题出现三种解释、开始重复问已回答的问题、完成标准被改宽松。</p><p>会话中断后，让它读 <code>PROGRESS.md</code> 末尾的状态快照接上，不要重做已完成任务。</p><h2 id="三、提示词" tabindex="-1">三、提示词 <a class="header-anchor" href="#三、提示词" aria-label="Permalink to “三、提示词”">​</a></h2><h3 id="_3-1-最小任务输入" tabindex="-1">3.1 最小任务输入 <a class="header-anchor" href="#_3-1-最小任务输入" aria-label="Permalink to “3.1 最小任务输入”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>任务：修复订单列表查询时状态筛选失效的问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标：</span></span>
<span class="line"><span>让状态筛选按照实际订单状态返回正确结果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>只修改订单列表查询相关逻辑，不改变其他筛选条件和接口返回结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>验收：</span></span>
<span class="line"><span>不同订单状态筛选结果正确，原有查询功能不受影响。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先检查现有实现，确认原因后直接修复并测试。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="_3-2-复杂任务输入" tabindex="-1">3.2 复杂任务输入 <a class="header-anchor" href="#_3-2-复杂任务输入" aria-label="Permalink to “3.2 复杂任务输入”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>【任务】</span></span>
<span class="line"><span>本次需要完成的具体事项。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【背景】</span></span>
<span class="line"><span>当前系统的业务情况、已有功能，以及为什么需要这次调整。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【目标】</span></span>
<span class="line"><span>1. 需要实现的功能。</span></span>
<span class="line"><span>2. 需要解决的问题。</span></span>
<span class="line"><span>3. 预期达到的效果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>- 允许修改的范围：</span></span>
<span class="line"><span>- 不允许修改的范围：</span></span>
<span class="line"><span>- 必须保持兼容的内容：</span></span>
<span class="line"><span>- 技术或业务限制：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【验收标准】</span></span>
<span class="line"><span>1. 功能行为：</span></span>
<span class="line"><span>2. 数据正确性：</span></span>
<span class="line"><span>3. 接口兼容性：</span></span>
<span class="line"><span>4. 测试要求：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【交付要求】</span></span>
<span class="line"><span>- 完成代码修改。</span></span>
<span class="line"><span>- 执行必要的编译和测试。</span></span>
<span class="line"><span>- 说明修改文件、实现结果和验证证据。</span></span>
<span class="line"><span>- 汇总未解决的问题和风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先分析任务，识别必要信息和潜在风险，再制定执行方案。</span></span>
<span class="line"><span>不要为了补充无关信息而反复提问。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br></div></div><h3 id="_3-3-集中提问规则" tabindex="-1">3.3 集中提问规则 <a class="header-anchor" href="#_3-3-集中提问规则" aria-label="Permalink to “3.3 集中提问规则”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>在执行任务前，请先检查现有代码、项目文档和相关业务实现。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对于缺失信息，按以下规则处理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 能从现有项目中确认的信息，不要询问我。</span></span>
<span class="line"><span>2. 可以通过安全的代码检查验证的信息，先自行检查。</span></span>
<span class="line"><span>3. 不影响业务正确性的细节，可以采用符合项目现有规范的合理方案。</span></span>
<span class="line"><span>4. 涉及业务规则、数据一致性、权限、安全、不可逆操作或兼容性的重要问题，不能自行猜测。</span></span>
<span class="line"><span>5. 将所有真正阻塞执行的问题集中整理，一次性向我提问。</span></span>
<span class="line"><span>6. 如果没有阻塞问题，直接制定方案并执行，不要逐步询问我是否继续。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果存在非阻塞风险，可以记录并说明处理依据，不要因此中断整个任务。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="_3-4-任务分级" tabindex="-1">3.4 任务分级 <a class="header-anchor" href="#_3-4-任务分级" aria-label="Permalink to “3.4 任务分级”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请先判断本次任务的执行级别：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>L1：范围明确、影响较小，可以直接实施。</span></span>
<span class="line"><span>L2：涉及多个文件或业务逻辑，需要先分析影响并制定简要方案。</span></span>
<span class="line"><span>L3：涉及多模块、核心业务、数据结构、系统集成或高风险操作，需要完整分析和分阶段执行。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>判断时考虑：</span></span>
<span class="line"><span>- 修改范围</span></span>
<span class="line"><span>- 业务复杂度</span></span>
<span class="line"><span>- 数据影响</span></span>
<span class="line"><span>- 接口兼容性</span></span>
<span class="line"><span>- 回归风险</span></span>
<span class="line"><span>- 是否存在不可逆操作</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请说明判断结果和原因，然后采用对应的执行流程。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要把简单任务复杂化，也不要把复杂任务当成简单任务直接修改。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h3 id="_3-5-方案生成" tabindex="-1">3.5 方案生成 <a class="header-anchor" href="#_3-5-方案生成" aria-label="Permalink to “3.5 方案生成”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的任务只有一个：基于我已经提供的上下文，产出技术方案和风险清单。</span></span>
<span class="line"><span>本轮不要修改任何代码，不要创建任何文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>任务：&lt;一句话说明要做什么&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>已有上下文：</span></span>
<span class="line"><span>- 涉及模块与文件：&lt;来自项目准备页的分析结果&gt;</span></span>
<span class="line"><span>- 相关调用链：&lt;入口 → 服务 → 数据&gt;</span></span>
<span class="line"><span>- 数据库与接口现状：&lt;表、字段、接口契约&gt;</span></span>
<span class="line"><span>- 已知约束与禁改区：&lt;来自项目规则&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按以下结构输出：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 需求复述（三句话内）</span></span>
<span class="line"><span>2. 仍模糊、会影响实现的问题（最多 8 条，按影响排序）</span></span>
<span class="line"><span>3. 本次不做项（至少 3 条）</span></span>
<span class="line"><span>4. 方案比较（2–3 个方案，逐项对比改动范围、数据影响、兼容性、回滚成本、验证难度）</span></span>
<span class="line"><span>5. 推荐方案与理由（按业务正确性 → 兼容性 → 改动范围 → 复用 → 可验证性排序）</span></span>
<span class="line"><span>6. 修改范围三栏（允许修改 / 禁止修改 / 必须保持兼容）</span></span>
<span class="line"><span>7. 风险清单（风险 → 触发条件 → 影响 → 处理 → 谁确认）</span></span>
<span class="line"><span>8. 子任务拆解（编号 | 任务 | 涉及文件 | 依赖 | 完成标准 | 验收方式）</span></span>
<span class="line"><span>9. 执行顺序与检查点</span></span>
<span class="line"><span>10. 需要我拍板的问题（没有就写「无，可以开始」）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>特别要求：</span></span>
<span class="line"><span>- 不要输出实现代码。</span></span>
<span class="line"><span>- 不要为了让方案完整而编造项目里不存在的组件或服务。</span></span>
<span class="line"><span>- 无法判断的部分明确标「待确认」，不要自行假设。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><h3 id="_3-6-启动连续执行" tabindex="-1">3.6 启动连续执行 <a class="header-anchor" href="#_3-6-启动连续执行" aria-label="Permalink to “3.6 启动连续执行”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>接下来的任务按连续执行方式进行。本轮先不要开始写代码，只确认执行规则。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>已提供：</span></span>
<span class="line"><span>- TASK-PLAN.md：&lt;路径&gt;</span></span>
<span class="line"><span>- PROGRESS.md：&lt;路径&gt;</span></span>
<span class="line"><span>- 全局 Rules：&lt;路径&gt;</span></span>
<span class="line"><span>- 本次 Spec：&lt;路径&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请确认以下规则，然后开始第一轮：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 每轮只执行一个 pending 子任务，按依赖顺序选，不要跳。</span></span>
<span class="line"><span>2. 每轮开始先读 TASK-PLAN.md 和 PROGRESS.md 末尾的状态快照。</span></span>
<span class="line"><span>3. 严格遵守「不做项」和「修改范围」，超出范围先停下来说明。</span></span>
<span class="line"><span>4. 每个子任务完成后必须执行完成标准对应的命令，原样记录输出。</span></span>
<span class="line"><span>5. 每轮结束写入 PROGRESS.md，更新状态快照，然后提交。</span></span>
<span class="line"><span>6. 验证失败记录错误原文，同一错误尝试不超过 3 次；达到上限标 blocked 并说明原因。</span></span>
<span class="line"><span>7. 到达检查点时停下来等我确认，不要自行通过。</span></span>
<span class="line"><span>8. 不要自己宣布整个任务完成——最终验收由我对照验收清单判定。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果以上规则可行，请从 T1 开始执行第一轮。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><h3 id="_3-7-中断恢复" tabindex="-1">3.7 中断恢复 <a class="header-anchor" href="#_3-7-中断恢复" aria-label="Permalink to “3.7 中断恢复”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我需要恢复一个中断的开发任务。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先读取：</span></span>
<span class="line"><span>- &lt;TASK-PLAN.md 路径&gt;</span></span>
<span class="line"><span>- &lt;PROGRESS.md 路径&gt;</span></span>
<span class="line"><span>- 当前 git status 与 git log -3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>然后只做四件事：</span></span>
<span class="line"><span>1. 复述当前状态：已完成哪些、进行中是哪个、下一轮是谁。</span></span>
<span class="line"><span>2. 核对文件状态与 PROGRESS.md 是否一致；不一致的列出来，不自行猜测原因。</span></span>
<span class="line"><span>3. 指出上一轮遗留的问题和未解决的阻塞。</span></span>
<span class="line"><span>4. 等我确认后，从下一轮任务继续执行。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要重新做已经完成的任务，不要删除已有改动。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h3 id="_3-8-日常最简指令" tabindex="-1">3.8 日常最简指令 <a class="header-anchor" href="#_3-8-日常最简指令" aria-label="Permalink to “3.8 日常最简指令”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请根据我提供的任务，先检查项目现状并判断任务复杂度。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 优先从项目代码和文档中补全必要上下文。</span></span>
<span class="line"><span>2. 区分已确认信息、可验证信息和待确认信息。</span></span>
<span class="line"><span>3. 只有真正影响业务正确性或执行安全的问题才集中询问我。</span></span>
<span class="line"><span>4. 根据任务复杂度选择最轻量的合理执行流程。</span></span>
<span class="line"><span>5. 严格遵守修改范围，不擅自重构或扩大需求。</span></span>
<span class="line"><span>6. 完成后执行必要的编译、测试和回归检查。</span></span>
<span class="line"><span>7. 最终提供修改内容、验证证据和遗留风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果没有阻塞问题，请直接执行，不要在每个小步骤都等待我的确认。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="_3-9-通用验收指令" tabindex="-1">3.9 通用验收指令 <a class="header-anchor" href="#_3-9-通用验收指令" aria-label="Permalink to “3.9 通用验收指令”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>任务完成后，请不要直接宣布完成。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按照本次任务的级别执行验收：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 检查实际修改是否符合任务目标。</span></span>
<span class="line"><span>2. 检查是否超出约定的修改范围。</span></span>
<span class="line"><span>3. 执行能够完成的编译、测试和静态检查。</span></span>
<span class="line"><span>4. 检查对原有功能和接口的影响。</span></span>
<span class="line"><span>5. 对无法验证的内容明确说明原因。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终提供：</span></span>
<span class="line"><span>- 完成内容</span></span>
<span class="line"><span>- 修改文件</span></span>
<span class="line"><span>- 关键实现说明</span></span>
<span class="line"><span>- 实际执行的验证命令</span></span>
<span class="line"><span>- 验证结果</span></span>
<span class="line"><span>- 未解决的问题和风险</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不得编造测试结果，不得将未执行的检查描述为通过。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h2 id="四、验收标准" tabindex="-1">四、验收标准 <a class="header-anchor" href="#四、验收标准" aria-label="Permalink to “四、验收标准”">​</a></h2><h3 id="执行前检查" tabindex="-1">执行前检查 <a class="header-anchor" href="#执行前检查" aria-label="Permalink to “执行前检查”">​</a></h3><ul><li>[ ] 需求已复述，模糊点已澄清或标注。</li><li>[ ] 有至少三条「本次不做项」。</li><li>[ ] 多方案处有比较表，取舍理由符合优先级。</li><li>[ ] 修改范围三栏落到具体文件路径。</li><li>[ ] 风险清单每条有处理动作和确认人。</li><li>[ ] 子任务可独立执行、独立验收，依赖与顺序清楚。</li><li>[ ] 每个完成标准写成了命令、diff 特征或页面行为。</li><li>[ ] 构建与测试命令已确认可用；缺测试环境的已写明替代检查。</li><li>[ ] 需要人工确认的事项已确认。</li></ul><h3 id="任务分级验收" tabindex="-1">任务分级验收 <a class="header-anchor" href="#任务分级验收" aria-label="Permalink to “任务分级验收”">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>必须做到</th></tr></thead><tbody><tr><td>L1</td><td>符合目标、没扩大范围、执行局部检查、说明结果</td></tr><tr><td>L2</td><td>功能符合预期、相关模块正常、编译或测试通过、检查关键回归、说明遗留</td></tr><tr><td>L3</td><td>核心业务规则验证、数据状态正确、接口兼容检查、异常场景验证、模块回归、迁移方案检查、证据与遗留齐全</td></tr></tbody></table><h3 id="每轮门禁" tabindex="-1">每轮门禁 <a class="header-anchor" href="#每轮门禁" aria-label="Permalink to “每轮门禁”">​</a></h3><p>一个子任务要标 <code>done</code>，必须同时满足：完成标准达成、验证命令已执行且输出原文已记录、改动文件都在允许范围、不做项未被触碰、无未记录问题、已提交且有明确 hash。</p><h3 id="执行阶段最容易犯的错" tabindex="-1">执行阶段最容易犯的错 <a class="header-anchor" href="#执行阶段最容易犯的错" aria-label="Permalink to “执行阶段最容易犯的错”">​</a></h3><ul><li><strong>只有方案没有拆解</strong>：AI 一次改十几个文件，出错无法定位。</li><li><strong>方案里没有不做项</strong>：AI 按自己的理解顺手扩大范围。</li><li><strong>风险写成「可能有风险」</strong>：执行时还是不知道怎么处理。</li><li><strong>一轮改完所有子任务</strong>：无法单独验证、单独回滚。</li><li><strong>失败后无限重试</strong>：在同一个错误认知上打转。</li><li><strong>检查点也问「要不要继续」</strong>：把连续执行变回逐步等待。</li></ul><p>具体场景的可复制提示词见 <a href="/my-vitepress-site/ai/prompts/coding.html">提示词库 · 编程开发</a>；本页管流程与验收，不重复维护相同模板。</p><p><strong>执行完成、准备验收时进入 <a href="/my-vitepress-site/ai/productivity/coding-sop/04-delivery-reuse.html">第 04 页 · 交付验收</a>。遇到报错和测试失败先看 <a href="/my-vitepress-site/ai/productivity/coding-sop/03-debug-fix.html">第 03 页 · 问题解决</a>。</strong></p>`,69)])])}const m=n(l,[["render",i]]);export{u as __pageData,m as default};
